/* 3챕터 장비 효과 점검 (10월 8일, docs/아이템/3챕터-장비.md 8절): 06a2의 게임 코드를 vm에서 그대로 돌려, 장비의 새 지점과 핵심 효과가 문장대로 일어나는지 장면마다 확인한다.
   itemcheck는 "발동했는가"를 세고, 이 점검은 "문장대로 바뀌었는가"를 본다. 실패 0이어야 한다.
   실행: DGDIR=06a2 node tools/item3check.js */
process.env.DGDIR = process.env.DGDIR || '06a2';
const D = require('./dgqa.js'); const G0 = D.G0; const run_ = D.run_;
let fail = 0, pass = 0; const ok = (c, m) => { if (c) pass++; else { fail++; console.log('실패:', m); } };
const V = k => run_(k);
function battle(room, build, lv, items) {
  const bd = build || 'warden';
  const p = G0.mkPlayer(bd, {}, G0.statRecommend(bd, {}, 15 + 2 * ((lv || 13) - 1)), G0.TREE2[bd].starters); p.lv = lv || 13;
  for (const k of items || []) p.eq[G0.ITEMS[k].slot] = k;
  p.stat.wil = 0; G0.applyStats(p, p.stat || {}); p.hp = p.hpMax; p.st = p.stMax;
  const r = Object.assign({ ch: 3, lv: 11, floor: 14, names: V('ENEMY_NAMES[3]'), path: 'main', en: [] }, room);
  const b = G0.roomBattle(p, r, r.boss ? 'queen' : null, 7); b.stepMode = false; for (const e of b.en) { e.hpMax = 100000; e.hp = 100000; } return b; /* 한 번에 쓰러지지 않게 생명력을 부풀린다 */
}
const al = b => G0.alive(b);
/* 한 번 친다: 행동 번호를 올리고 b.cur를 두고 hurtEnemy를 부른다 */
function hit(b, e, raw, cur, o) { b.actN = (b.actN || 0) + 1; b.cur = cur || { id: 'basic' }; const h0 = e.hp; G0.hurtEnemy(b, e, raw, o || { single: 1, melee: 1 }); b.cur = null; return h0 - e.hp; }
function T(name, f) { try { f(); } catch (x) { ok(false, name + ' 예외: ' + (x && x.stack ? x.stack.split('\n').slice(0, 3).join(' | ') : x)); } }
const near = (a, b, tol) => Math.abs(a - b) <= (tol || 0.6);

/* 풀: 세 풀의 장비 id가 겹치지 않는다(겹치면 데이터가 서로 덮는다), 3챕터 풀은 200종 */
T('pools', () => { const P = [V('CH1_POOL'), V('CH2_POOL'), V('CH3_POOL')]; const all = [].concat(...P); ok(new Set(all).size === all.length, '세 풀의 장비 id가 겹친다: ' + all.filter((k, i) => all.indexOf(k) !== i).join(', ')); ok(P[2].length === 200, '3챕터 풀 ' + P[2].length + '종'); ok(P[2].every(k => V('IFX["' + k + '"]')), '효과가 없는 3챕터 장비'); });
/* 드롭: 3챕터 등급 확률, 같은 전설은 한 런에 한 번, 전설이 떨어지면 영웅으로 바꾼다 */
T('drops', () => {
  const tally = (src, n) => { const c = { n: 0, m: 0, r: 0, h: 0, l: 0 }; for (let i = 0; i < n; i++) c[G0.rollGradeCh(3, src)]++; return c; };
  const rm = tally('room', 200000); const near2 = (v, t, tol) => Math.abs(v / 2000 - t) <= tol;
  ok(near2(rm.n, 50, 1) && near2(rm.m, 32, 1) && near2(rm.r, 14, 0.7) && near2(rm.h, 3.4, 0.4) && near2(rm.l, 0.6, 0.2), '3챕터 일반 · 매복 등급 확률 ' + JSON.stringify(rm));
  const bg = tally('big', 100000); ok(bg.n === 0 && bg.m === 0 && Math.abs(bg.h / 1000 - 10) < 1 && Math.abs(bg.l / 1000 - 2) < 0.6, '3챕터 강적 · 시련 · 보물: 희귀 이상만 ' + JSON.stringify(bg));
  const bs = tally('boss', 100000); ok(bs.n === 0 && bs.m === 0 && Math.abs(bs.h / 1000 - 32) < 1.5 && Math.abs(bs.l / 1000 - 8) < 1, '3챕터 보스: 희귀 이상만 ' + JSON.stringify(bs));
  const p = battle({ en: [['bruiser', 0]] }, 'assassin', 13, []).p; const run = { p, ch: 3, inv: {}, legSeen: [] }; const L3 = V('CH3_POOL'); const got = []; for (let i = 0; i < 12; i++) got.push(G0.dropKey(run, 'l'));
  const legs = got.filter(k => G0.ITEMS[k].g === 'l');
  ok(legs.length === 8 && new Set(legs).size === 8 && legs.every(k => L3.includes(k)), '같은 전설은 한 런에 한 번: 3챕터 전설 8종이 하나씩 (' + legs.length + '종)');
  ok(got.slice(8).every(k => G0.ITEMS[k].g === 'h' && L3.includes(k)), '전설이 떨어지면 영웅으로 바뀐다');
  const old = []; for (let i = 0; i < 3000; i++) old.push(G0.dropKey({ p, ch: 3, inv: {}, legSeen: [] }, 'm')); const share = old.filter(k => !L3.includes(k)).length / old.length; ok(share > 0.07 && share < 0.13 && old.filter(k => !L3.includes(k)).every(k => V('CH2_POOL').includes(k)), '고급 드롭의 10%는 2챕터 풀 (' + share.toFixed(3) + ')');
});
/* 허상 */
T('mirrorlance', () => { const b = battle({ en: [['bruiser', 0]] }, 'assassin', 13, ['mirrorlance']); const e = b.en[0]; e.haze = 1; const d = hit(b, e, 100); ok(near(d, 30, 1) && e.haze === 0, '신기루 창: 허상을 걷어도 30%가 들어간다 (' + d + ')'); });
T('gazebow', () => { const b = battle({ en: [['bruiser', 0]] }, 'hunter', 13, ['gazebow']); const e = b.en[0]; e.haze = 1; b.p.focus = { id: e.id, n: 2 }; const d = hit(b, e, 100, { id: 'basic', ranged: 1 }, { single: 1 }); ok(e.haze === 1 && d > 90, '응시하는 활: 추적 2겹이면 허상을 꿰뚫는다 (' + d + ', 허상 ' + e.haze + ')'); });
T('glassknife', () => { const b = battle({ en: [['bruiser', 0]] }, 'assassin', 13, ['glassknife']); const e = b.en[0]; e.haze = 1; b.p.st = 40; hit(b, e, 50); ok(b.p.st === 46 && e.haze === 0, '깨진 거울 칼: 허상을 걷으면 스태미나 +6 (' + b.p.st + ')'); });
T('hazeking', () => { const b = battle({ en: [['bruiser', 0]] }, 'assassin', 13, ['hazeking']); const e = b.en[0]; e.haze = 1; const d = hit(b, e, 100); ok(near(d, 62.5, 1.5), '신기루 왕의 대검: 50% × 1.25 (' + d + ')'); });
T('kiamulet3', () => { const b = battle({ en: [['bruiser', 0]] }, 'monk', 13, ['kiamulet3']); const e = b.en[0]; e.haze = 1; G0.addS(b, b.p, 'empower', 1); const d = hit(b, e, 100); ok(e.haze === 1 && d > 60, '기 모으는 목걸이: 기를 실은 공격은 허상을 걷지 않고 지나간다 (' + d + ', 허상 ' + e.haze + ')'); });
T('shadowsickle', () => { const b = battle({ en: [['bruiser', 0], ['bruiser', 0]] }, 'assassin', 13, ['shadowsickle']); const e = b.en[0]; e.haze = 1; b.actN = 5; G0.fxRun(b.p, 'onParry', b, b.p, b.en[1]); const d = hit(b, e, 100); ok(e.haze === 1 && d > 60, '그림자 낫: 흘린 뒤 첫 공격은 허상을 꿰뚫는다 (' + d + ')'); const e2 = b.en[1]; e2.haze = 1; hit(b, e2, 100); ok(e2.haze === 0, '그림자 낫: 효과는 한 행동뿐 (허상 ' + e2.haze + ')'); });
T('hazering', () => { const b = battle({ en: [['bruiser', 0]] }, 'assassin', 13, ['hazering']); const e = b.en[0]; e.haze = 1; hit(b, e, 10); const d0 = hit(b, e, 100); const b2 = battle({ en: [['bruiser', 0]] }, 'assassin', 13, []); const e2 = b2.en[0]; e2.haze = 1; hit(b2, e2, 10); const d1 = hit(b2, e2, 100); ok(near(d0 / d1, 1.08, 0.01), '신기루 반지: 허상을 걷은 라운드에 +8% (' + (d0 / d1).toFixed(3) + ')'); });
T('veilblade', () => { const b = battle({ en: [['bruiser', 0], ['bruiser', 0]] }, 'assassin', 13, ['veilblade']); b.en[0].haze = 1; hit(b, b.en[0], 10); const d = hit(b, b.en[1], 100); const b2 = battle({ en: [['bruiser', 0], ['bruiser', 0]] }, 'assassin', 13, []); const d2 = hit(b2, b2.en[1], 100); ok(near(d / d2, 1.15, 0.01), '베일 가르는 칼: 다음 행동 +15% (' + (d / d2).toFixed(3) + ')'); const d3 = hit(b, b.en[1], 100); ok(near(d3 / d2, 1, 0.01), '베일 가르는 칼: 한 행동뿐'); });
T('hazebind', () => { const b = battle({ en: [['bruiser', 0], ['archer', 0]], mods: ['haze'] }, 'assassin', 13, ['hazebind']); ok(b.en.every(e => e.haze === 1), '아지랑이 방은 허상으로 시작'); G0.fxRun(b.p, 'onAct', b, b.p, 'basic', {}, null); ok(b.en.every(e => !(e.haze > 0)) && b.p.ward >= 0, '허상 엮는 반지: 첫 행동에 허상이 한 겹 걷힌다 (' + b.en.map(e => e.haze).join(',') + ')'); });
T('mirage_hand', () => { const b = battle({ en: [['bruiser', 0], ['bruiser', 0]] }, 'assassin', 13, ['mirage_hand']); b.p.ward = 0; const e = b.en[0]; const h0 = b.p.hp; G0.hurtPlayer(b, 20, { src: e, single: 1, label: '시험' }); G0.hurtPlayer(b, 20, { src: e, single: 1, label: '시험' }); ok(b.p.hp === h0, '신기루의 손: 허상 2겹이 한 적 대상 공격 둘을 헛치게 한다'); G0.hurtPlayer(b, 20, { src: e, single: 1, label: '시험' }); ok(b.p.hp < h0, '신기루의 손: 셋째는 들어온다'); b.en[1].haze = 1; hit(b, b.en[1], 10); const h1 = b.p.hp; G0.hurtPlayer(b, 20, { src: e, single: 1, label: '시험' }); ok(b.p.hp === h1, '신기루의 손: 적의 허상을 걷으면 내 허상이 한 겹 생긴다'); });
T('mirageplate', () => { const b = battle({ en: [['bruiser', 0]] }, 'assassin', 13, ['mirageplate']); b.p.ward = 0; const h0 = b.p.hp; G0.hurtPlayer(b, 20, { src: b.en[0], single: 1, label: '시험' }); ok(b.p.hp === h0, '신기루 판금: 처음 받는 직접 피해는 허상이 맞는다'); G0.hurtPlayer(b, 20, { src: b.en[0], single: 1, label: '시험' }); ok(b.p.hp < h0, '신기루 판금: 한 번뿐'); });
/* 붕대 */
T('burnscythe', () => { const b = battle({ en: [['wrapped', 0], ['bruiser', 0]] }, 'assassin', 13, ['burnscythe']); const e = b.en[0]; ok(e.wrap === 3, '붕대 3'); const k0 = e.brk; G0.addS(b, e, 'ignite', 1); ok(!e.wrap && e.brk >= k0 + 10, '불사르는 낫: 붕대가 타면 붕괴 +10 (' + (e.brk - k0) + ')'); });
T('unravel', () => { const b = battle({ en: [['wrapped', 0], ['wrapped', 0], ['bruiser', 0]] }, 'assassin', 13, ['unravel']); G0.addS(b, b.en[0], 'ignite', 1); ok(!b.en[0].wrap && !b.en[1].wrap, '풀어 헤치는 칼: 붕대 하나가 벗겨지면 다른 붕대도 풀린다 (' + b.en[0].wrap + ',' + b.en[1].wrap + ')'); ok(G0.st(b.en[0], 'vuln') === 2, '풀어 헤치는 칼: 취약 2'); });
