T('cinderaxe', () => { const b = battle({ en: [['wrapped', 0]] }, 'assassin', 13, ['cinderaxe']); const e = b.en[0]; b.p.st = 40; hit(b, e, 10); ok(!e.wrap && b.p.st === 48, '붕대 사르는 도끼: 붕대를 태우고 스태미나 +8 (' + e.wrap + ', ' + b.p.st + ')'); });
T('wrapripper', () => { const mk = it => { const b = battle({ en: [['wrapped', 0]] }, 'assassin', 13, it); return hit(b, b.en[0], 100); }; const r = mk(['wrapripper']) / mk([]); ok(near(r, 1.12, 0.01), '붕대 푸는 쇠갈고리: 붕대 감긴 적에게 +12% (' + r.toFixed(3) + ')'); });
T('poisonwrap', () => { const b = battle({ en: [['wrapped', 0], ['wrapped', 0]] }, 'assassin', 13, ['poisonwrap']); G0.fxRun(b.p, 'onSkill', b, b.p, { id: 'x', s: { fx: [{ k: 'burst' }] } }); ok(b.en.every(e => !e.wrap), '독 삼킨 장갑: 독을 터뜨리면 붕대가 모두 풀린다'); });
T('wrapmail', () => { const b = battle({ en: [['bruiser', 0]] }, 'assassin', 13, ['wrapmail']); b.p.ward = 0; const e = b.en[0]; const hp = () => b.p.hp; const base = battle({ en: [['bruiser', 0]] }, 'assassin', 13, []); base.p.ward = 0; const h0 = base.p.hp; G0.hurtPlayer(base, 30, { src: base.en[0], single: 1, label: '시험' }); const lost0 = h0 - base.p.hp; const h1 = hp(); G0.hurtPlayer(b, 30, { src: e, single: 1, label: '시험' }); const lost1 = h1 - hp(); ok(near(lost1 / lost0, 0.7, 0.02), '굳은 붕대 갑옷: 붕대가 감긴 동안 −30% (' + (lost1 / lost0).toFixed(3) + ')'); });
T('mirrorarmor', () => { const b = battle({ en: [['bruiser', 0]] }, 'assassin', 13, ['mirrorarmor']); b.p.ward = 0; const e = b.en[0]; e.haze = 1; e.wrap = 3; const hp0 = e.hp; G0.hurtPlayer(b, 40, { src: e, single: 1, label: '시험' }); ok(e.hp < hp0 && e.haze === 1 && e.wrap === 3, '거울 갑옷: 때린 적에게 되돌린다, 허상 · 붕대는 지나간다 (' + (hp0 - e.hp).toFixed(1) + ')'); });
